use vstd::prelude::*;

verus! {

fn concatenate(a: Vec<f32>, b: Vec<f32>) -> (c: Vec<f32>)
    ensures
        c@.len() == a@.len() + b@.len(),
        forall|i: int|
            0 <= i < a@.len() ==> c@[i] == a@[i],
        forall|j: int|
            0 <= j < b@.len() ==> c@[a@.len() + j] == b@[j],
{
    let mut c: Vec<f32> = Vec::new();

    // Push all of `a`
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a@.len(),
            c@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> c@[k] == a@[k],
        decreases a.len() - i,
    {
        c.push(a[i]);
        i = i + 1;
    }

    // Push all of `b`
    let a_len: usize = a.len();
    let mut j: usize = 0;
    while j < b.len()
        invariant
            j <= b@.len(),
            c@.len() == a@.len() + j as int,
            // first segment still matches `a`
            forall|k: int| 0 <= k < a@.len() ==> c@[k] == a@[k],
            // appended portion matches `b[0..j)`
            forall|k: int| 0 <= k < j as int ==> c@[a@.len() + k] == b@[k],
        decreases b.len() - j,
    {
        c.push(b[j]);
        j = j + 1;
    }

    // Help the verifier relate `a.len()` (usize) to `a@.len()` (int)
    assert(a_len as int == a@.len());

    c
}

} // verus!

